import http.server
import json
import re
import socketserver
import os
import anthropic

PORT = int(os.environ.get("PORT", 8000))

SYSTEM_INSTRUCTION = """You are a deterministic prompt rewriting engine. You receive a raw technical description and output a single fully rewritten production build prompt. Follow these rules with zero deviation:

STEP 1 - INPUT NORMALIZATION:
Accept the raw text. Preserve all technical meaning. Remove only redundant whitespace. Do not paraphrase yet.

STEP 2 - STRUCTURE EXTRACTION:
Identify and extract: system goal, required features, constraints, architecture requirements, implementation rules. If any category is missing, infer only minimal necessary structure without adding new product features.

STEP 3 - PROMPT RECONSTRUCTION:
Convert extracted structure into a single continuous instruction set. Must be strictly imperative and implementation-focused. Must not include explanations, commentary, or meta-text. Must not include role assignment, persona, or expertise framing. Must not include polite language or conversational filler.

STEP 4 - HARD CONSTRAINTS ENFORCEMENT:
Replace any vague wording with explicit implementation instructions. Convert abstract goals into concrete system behaviors. Ensure all requirements are expressed as executable build steps. Do not remove constraints unless they are logically redundant.

STEP 5 - OUTPUT FORMATTING:
Output must be a single continuous prompt. No bullet explanations about the transformation process. No markdown formatting inside the returned prompt. No headings unless explicitly required by the input description.

STEP 6 - STRUCTURAL ENFORCEMENT:
If backend is required in instructions: enforce SINGLE-FILE Python backend. If frontend is required in instructions: enforce SINGLE index.html file containing all UI, routing, and views. If full application is requested: require complete production-ready code with no placeholders, no mocks, no dummy implementations.

STEP 7 - SAFETY:
Do not invent features not implied by input. Do not reference external software names or known products. Do not include explanations of reasoning.

OUTPUT: Return only the rewritten prompt text. Nothing else. No preamble. No postamble."""

def rewrite_prompt(description: str) -> str:
    description = re.sub(r'[ \t]+', ' ', description)
    description = re.sub(r'\n{3,}', '\n\n', description).strip()

    client = anthropic.Anthropic()

    response = client.messages.create(
        model="claude-opus-4-5",
        max_tokens=16000,
        thinking={
            "type": "enabled",
            "budget_tokens": 10000
        },
        temperature=1,
        system=SYSTEM_INSTRUCTION,
        messages=[
            {
                "role": "user",
                "content": description
            }
        ]
    )

    result_text = ""
    for block in response.content:
        if block.type == "text":
            result_text += block.text

    return result_text.strip()

class Handler(http.server.BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass

    def do_OPTIONS(self):
        self.send_response(200)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.end_headers()

    def do_POST(self):
        if self.path != "/convert":
            self.send_response(404)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(json.dumps({"error": "Not found"}).encode())
            return

        content_length = int(self.headers.get("Content-Length", 0))
        if content_length == 0:
            self.send_response(400)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(json.dumps({"error": "Empty request body"}).encode())
            return

        body = self.rfile.read(content_length)

        try:
            data = json.loads(body)
        except json.JSONDecodeError:
            self.send_response(400)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(json.dumps({"error": "Invalid JSON"}).encode())
            return

        description = data.get("description", "").strip()
        if not description:
            self.send_response(400)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(json.dumps({"error": "Missing or empty description field"}).encode())
            return

        try:
            prompt = rewrite_prompt(description)
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(json.dumps({"prompt": prompt}).encode())
        except anthropic.APIConnectionError as e:
            self.send_response(503)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(json.dumps({"error": f"API connection error: {str(e)}"}).encode())
        except anthropic.RateLimitError as e:
            self.send_response(429)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(json.dumps({"error": f"Rate limit exceeded: {str(e)}"}).encode())
        except anthropic.APIStatusError as e:
            self.send_response(502)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(json.dumps({"error": f"API error {e.status_code}: {e.message}"}).encode())
        except Exception as e:
            self.send_response(500)
            self.send_header("Content-Type", "application/json")
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(json.dumps({"error": f"Internal server error: {str(e)}"}).encode())

with socketserver.TCPServer(("", PORT), Handler) as httpd:
    httpd.allow_reuse_address = True
    print(f"Serving on port {PORT}")
    httpd.serve_forever()
