const dark=theme==='dark';
root.setAttribute('data-theme',theme);
themeToggle.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');
themeToggle.innerHTML=dark?'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg>':'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="5"></circle><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"></path></svg>';
}
renderThemeIcon();
themeToggle.addEventListener('click',function(){theme=theme==='dark'?'light':'dark';renderThemeIcon();});
const description=document.getElementById('description');
const convertButton=document.getElementById('convertButton');
const clearButton=document.getElementById('clearButton');
const buttonText=document.getElementById('buttonText');
const buttonLoader=document.getElementById('buttonLoader');
const output=document.getElementById('output');
const status=document.getElementById('status');
let loading=false;
function setLoading(next){
loading=next;
convertButton.disabled=next;
description.disabled=next;
buttonLoader.classList.toggle('hidden',!next);
buttonText.textContent=next?'Converting...':'Convert';
if(next){
status.className='status';
status.innerHTML='<span class="inline-loader"><span class="spinner" aria-hidden="true"></span><span>Átalakítás folyamatban...</span></span>';
}else if(status.textContent.trim()==='Átalakítás folyamatban...'){
status.textContent='';
}
}
function showOutput(text){
output.classList.remove('empty');
output.textContent=text;
}
function showEmpty(){
output.classList.add('empty');
output.textContent='Itt jelenik meg a visszaadott prompt.';
}
function showError(message){
status.className='status error';
status.textContent=message;
}
function showSuccess(message){
status.className='status success';
status.textContent=message;
}
async function convert(){
if(loading){return;}
const value=description.value.trim();
if(!value){
showError('Adj meg egy technikai leírást a konvertálás előtt.');
showEmpty();
return;
}
setLoading(true);
try{
const response=await fetch('/convert',{
method:'POST',
headers:{'Content-Type':'application/json'},
body:JSON.stringify({description:value})
});
let data={};
try{data=await response.json();}catch(e){}
if(!response.ok){
throw new Error(data.error||'A backend nem tudta feldolgozni a kérést.');
}
if(typeof data.prompt!=='string' || !data.prompt.trim()){
throw new Error('A backend nem adott vissza érvényes promptot.');
}
showOutput(data.prompt.trim());
showSuccess('A prompt sikeresen elkészült.');
}catch(error){
showError(error.message||'Váratlan hiba történt.');
showEmpty();
}finally{
setLoading(false);
if(status.innerHTML.includes('Átalakítás folyamatban')){status.textContent='';}
}
}
convertButton.addEventListener('click',convert);
clearButton.addEventListener('click',function(){
description.value='';
status.textContent='';
